const filas = $('Leer agentes').all().map(i => i.json).filter(a => a && a.calendar_id && a.active === true);
const out = filas.map(a => ({ json: { agent_key: a.agent_key, display_name: a.display_name, calendar_id: a.calendar_id } }));
out.push({ json: { agent_key: '', display_name: 'General', calendar_id: 'consultingsimarroproperties@gmail.com' } });
return out;

// ── Reglas medidas contra 74 citas reales de las 7 agendas (10-sep-2026) ──
const norm = (s) => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9+\s]/g, ' ').replace(/\s+/g, ' ').trim();

const STOP = new Set(('visita visitas valoracion posible segunda a 2a 3a llamar llama revisar cribar preparar '
  + 'enviar confirmar cerrar mandar el la los las de del y en para que con al un una calle c av avenida urb '
  + 'urbanizacion bloque esc escalera piso chalet duplex atico local plaza paseo camino carretera ctra pza '
  + 'apuntito tengo semana pasada proxima manana tarde por su sus mi').split(' '));

// Calificador opcional delante de la palabra clave: "2a visita", "POSIBLE VALORACION".
const PREF = '(?:(?:\\d+\\s*[ao]?|primera|segunda|tercera|posible|nueva)\\s+)?';
const RE_VISITA     = new RegExp('^' + PREF + 'visita(s)?\\b');
const RE_VALORACION = new RegExp('^' + PREF + 'valoracion(es)?\\b');
const RE_SOLO_TIPO  = new RegExp('^' + PREF + '(?:visita(?:s)?|valoracion(?:es)?)$');

function telefono(t) {
  const s = String(t || '').replace(/[·]/g, ' ');
  const m = s.match(/\+\s?(\d{1,3})[\s.-]?((?:\d[\s.-]?){8,11}\d)/);
  if (m) return ('+' + m[1] + m[2].replace(/\D/g, '')).slice(0, 16);
  const re = /(?<!\d)([6-9](?:[\s.-]?\d){8})(?!\d)/g;
  let x;
  while ((x = re.exec(s)) !== null) {
    const d = x[1].replace(/\D/g, '');
    if (d.length === 9) return '+34' + d;
  }
  return '';
}
function nombre(t) {
  // Formato acordado con los agentes (10-sep): "VISITA - Nombre - Telefono - Direccion".
  // Si el titulo viene asi, el nombre se LEE del segundo campo en vez de adivinarse. Solo se
  // aplica cuando el primer campo es exactamente la palabra clave, para que un titulo suelto
  // con un guion ("Visita Blanca 607819241 - Villalba") no acabe llamando al cliente Villalba.
  const partes = String(t || '').split(/\s+[-\u2013\u2014|]\s+/).map(s => s.trim()).filter(Boolean);
  if (partes.length >= 2 && RE_SOLO_TIPO.test(norm(partes[0]))) {
    const limpio = norm(partes[1]).replace(/\+?\d[\d\s.-]{6,}\d/g, ' ').replace(/\b\d+\b/g, ' ');
    const ws = limpio.split(' ').filter(w => w && w.length > 1 && !STOP.has(w)).slice(0, 4);
    if (ws.length) return ws.map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  }
  // Sin separadores: heuristica de siempre, 1-2 palabras tras la palabra clave.
  let n = norm(t).replace(/\+?\d[\d\s.-]{6,}\d/g, ' ').replace(/\b\d+\b/g, ' ');
  const out = [];
  for (const w of n.split(' ')) {
    if (!w || w.length < 2 || STOP.has(w)) { if (out.length) break; else continue; }
    out.push(w);
    if (out.length === 2) break;
  }
  return out.map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}
// ── Vivienda de la visita: se deduce de lo que el agente escribe (titulo, ubicacion, descripcion) ──
// Regla de negocio (14-sep, Manu): la vivienda se captura por la CALLE o la ubicacion, no por la
// referencia de Idealista (0 de 74 citas reales la llevan). Orden:
//   1. referencia de Idealista si por casualidad aparece (1 + 8 cifras)
//   2. calle del anuncio: si casan varias (Hernan Cortes 4 = 10 pisos) se coge la primera
//   3. barrio o municipio, SOLO si en el catalogo activo hay una unica vivienda ahi
// Idealista oculta la calle en la mitad del catalogo (showAddress:false): por eso existe el paso 3.
function crearResolutorVivienda(catalogo, norm) {
  const VACIAS = new Set('de del la las los el y en a'.split(' '));
  const TIPO_VIA = 'calle|c|cl|avenida|avda|av|paseo|plaza|pza|camino|carretera|ctra|travesia|ronda|glorieta|urbanizacion|urb|pasaje|callejon|costanilla';
  const RE_TIPO_VIA = new RegExp('^(?:' + TIPO_VIA + ')\\b');
  // Palabras de lugar que no identifican nada por si solas.
  const GENERICAS = new Set(('madrid centro casco antiguo historico zona norte sur este oeste monte parque pueblo '
    + 'barrio nuevo nueva alta baja san santa santo collado villa plaza calle sol real ciudad urbanizacion').split(' '));
  const ORDINAL = {};
  'primer primera primero|segunda segundo|tercera tercero|cuarta cuarto|quinta quinto|sexta sexto|septima septimo|octava octavo|novena noveno|decima decimo'
    .split('|').forEach((g, i) => g.split(' ').forEach(w => { ORDINAL[w] = String(i + 1); }));
  const palabras = (s) => norm(s).split(' ').filter(w => w && !VACIAS.has(w));

  const props = (catalogo || []).filter(p => p && p.idealista_id);
  const lugaresDe = (p) => [p.municipality, p.district, p.neighborhood, p.province].filter(Boolean).map(String);

  // Palabras que tambien son nombre de lugar ("Toledo" es calle en Madrid y provincia de Mentrida):
  // una calle de una sola palabra de este tipo solo casa con "calle/c/avda..." delante.
  const palabrasDeLugar = new Set();
  for (const p of props) for (const l of lugaresDe(p)) for (const w of palabras(l)) palabrasDeLugar.add(w);

  const calles = [];
  for (const p of props) {
    const a = String(p.address || '');
    const i = a.indexOf(' en ');
    const via = norm((i >= 0 ? a.slice(i + 4) : a).split(',')[0]);
    if (!RE_TIPO_VIA.test(via)) continue; // sin calle publica: "Piso en Dehesa - El Soto, Collado Villalba"
    const nucleo = palabras(via.replace(RE_TIPO_VIA, ' '));
    if (!nucleo.length || nucleo.join('').length < 4) continue;
    const conPrefijo = nucleo.length === 1 && palabrasDeLugar.has(nucleo[0]);
    calles.push({ id: String(p.idealista_id), nucleo, conPrefijo, via });
  }

  const lugares = [];
  for (const p of props) {
    const trozos = [];
    for (const l of [p.municipality, p.district, p.neighborhood].filter(Boolean)) {
      for (const t of String(l).split(/\s+-\s+/)) trozos.push({ t, municipio: l === p.municipality });
    }
    for (const { t, municipio } of trozos) {
      const sig = palabras(t).filter(w => !GENERICAS.has(w));
      if (!sig.length || sig.join('').length < 5) continue;
      // Del municipio basta su palabra mas larga si tiene 7+ letras ("villaviciosa", "escorial").
      const larga = municipio ? sig.reduce((a, b) => (b.length > a.length ? b : a), '') : '';
      lugares.push({ id: String(p.idealista_id), sig, larga: larga.length >= 7 ? larga : '', nombre: t });
    }
  }

  return function viviendaDe(...textos) {
    const bruto = textos.filter(Boolean).join(' ');
    const ref = String(bruto).match(/(?<!\d)(1\d{8})(?!\d)/);
    if (ref) return { idealista_id: ref[1], via: 'referencia' };
    const t = ' ' + norm(bruto) + ' ';
    const esta = (w) => t.includes(' ' + w + ' ');
    // "4 dimension" / "4a dimension" es la calle Cuarta Dimension.
    const estaVia = (w) => esta(w) || (ORDINAL[w] ? [ORDINAL[w], ORDINAL[w] + 'a', ORDINAL[w] + 'o'].some(esta) : false);

    for (const c of calles) {
      if (!c.nucleo.every(estaVia)) continue;
      if (c.conPrefijo && !new RegExp(' (?:' + TIPO_VIA + ')(?: (?:de|del|la|las|los|el))* ' + c.nucleo[0] + ' ').test(t)) continue;
      return { idealista_id: c.id, via: 'calle: ' + c.via };
    }

    const ids = new Set(), nombres = new Set();
    for (const l of lugares) {
      if (l.sig.every(esta) || (l.larga && esta(l.larga))) { ids.add(l.id); nombres.add(l.nombre); }
    }
    if (ids.size === 1) return { idealista_id: [...ids][0], via: 'lugar: ' + [...nombres].join(' / ') };
    return { idealista_id: '', via: ids.size > 1 ? 'lugar ambiguo (' + ids.size + ' viviendas)' : '' };
  };
}

function clasificar(summary) {
  // Regla de negocio (10-sep, Ramon): solo es lead lo que el agente escribe empezando por
  // VISITA o por VALORACION. El resto de lo que hay en las agendas (llamadas, recordatorios,
  // reuniones internas, obras) no es un lead y se descarta.
  // Se admite un calificador delante ("2a visita", "POSIBLE VALORACION"): son visitas reales
  // y dejarlas fuera perdia citas de verdad.
  const n = norm(summary);
  const tel = telefono(summary);
  if (RE_VALORACION.test(n)) return { tipo: 'VALORACION', motivo: '', tel };
  if (RE_VISITA.test(n))     return { tipo: 'VISITA',     motivo: '', tel };
  return { tipo: 'DESCARTA', motivo: 'no empieza por VISITA ni VALORACION', tel };
}

// ── Destinos en Kommo ──
const AGENTE_ENUM = { 'ainhoa': 1021253, 'carlos': 1019679, 'elisa': 1033488, 'pedro': 1023055,
  'ramon simarro': 1019677, 'ramon santiago': 1033486 };
const DESTINO = {
  VALORACION: { pipeline_id: 13652227, status_id: 105358027 },
  VISITA:     { pipeline_id: 13546071, status_id: 107269819 },
  VISITA_SIN_TEL: { pipeline_id: 13546071, status_id: 104515787 },
};

const dry = (() => {
  for (const n of ['Modo simulacion', 'Modo aplicar', 'Modo real']) {
    try { const v = $(n).first().json; if (typeof v.dry === 'boolean') return v.dry; } catch (e) {}
  }
  return true;
})();

const agendas = $('Agendas').all().map(i => i.json);
const viviendaDe = crearResolutorVivienda($('Leer catálogo').all().map(i => i.json).filter(p => p && p.idealista_id), norm);
const respuestas = $('Leer eventos').all().map(i => i.json);

const eventos = [];
for (let i = 0; i < respuestas.length; i++) {
  const ag = agendas[i] || {};
  for (const ev of (respuestas[i].items || [])) {
    if (ev.status === 'cancelled') continue;
    eventos.push({ agente_key: ag.agent_key, agente: ag.display_name, calendar_id: ag.calendar_id,
      event_id: ev.id, summary: ev.summary || '', desc: ev.description || '', location: ev.location || '',
      start: (ev.start || {}).dateTime || null, start_dia: (ev.start || {}).date || null,
      ya: ((ev.extendedProperties || {}).private || {}).simarro_lead || '' });
  }
}

const ahora = Date.now();
// Solo eventos FUTUROS. Con margen hacia atras (antes: -24h) se creaban leads de citas ya
// celebradas y el salesbot de Kommo escribia al cliente por una visita pasada
// (10-sep: Esther, cita a las 11:00, WhatsApp a las 12:07). Ver Stack/incidents.md.
const LIMITE_PASADO = ahora;
const plan = [], saltados = [], marcar = [];
const vistos = new Map();

// Clave estable entre pasadas: telefono si lo hay, si no nombre+hora de inicio.
const claveDe = (summary, inicioISO) => {
  const t = telefono(summary);
  return t ? 'T' + t : 'N' + norm(nombre(summary) || 'sin nombre') + '|' + inicioISO;
};
const inicioDe = (e) => e.start || (e.start_dia ? e.start_dia + 'T10:00:00+02:00' : null);

// 1a pasada: lo que YA tiene lead reserva su clave, para que su gemelo en otra
// agenda no se cuele como lead nuevo en la pasada siguiente.
for (const e of eventos) {
  const yaLead = e.ya || (/Lead ID:\s*(\d+)/.exec(e.desc) || [])[1] || '';
  if (!yaLead) continue;
  const ini = inicioDe(e);
  if (ini) vistos.set(claveDe(e.summary, ini), { yaLead, gemelos: [], inicioISO: ini });
  saltados.push({ ...e, por: 'ya vinculado a ' + yaLead });
}

// 2a pasada: los candidatos.
for (const e of eventos) {
  if (e.ya || /Lead ID:/.test(e.desc)) continue;
  const inicioISO = inicioDe(e);
  if (!inicioISO) { saltados.push({ ...e, por: 'sin fecha' }); continue; }
  const ts = new Date(inicioISO).getTime();
  if (!(ts >= LIMITE_PASADO)) continue;
  const c = clasificar(e.summary);
  if (c.tipo === 'DESCARTA') { saltados.push({ ...e, por: c.motivo }); continue; }
  const nom = nombre(e.summary) || 'Sin nombre';
  const clave = claveDe(e.summary, inicioISO);
  if (vistos.has(clave)) {
    const v = vistos.get(clave);
    v.gemelos.push({ agente: e.agente, event_id: e.event_id });
    // 21-sep-2026: el gemelo de una cita YA vinculada se marca con el mismo lead ('Gemelos a marcar').
    // Solo a la MISMA hora: la clave por telefono no distingue dos citas distintas del mismo cliente.
    if (v.yaLead && new Date(v.inicioISO).getTime() === ts) {
      marcar.push({ calendar_id: e.calendar_id, event_id: e.event_id, agente: e.agente, lead: String(v.yaLead), inicioISO });
    }
    continue;
  }
  const d = (c.tipo === 'VISITA' && !c.tel) ? DESTINO.VISITA_SIN_TEL : DESTINO[c.tipo];
  // Solo en VISITA: en una VALORACION la casa es la del propietario y no esta en el catalogo.
  const viv = c.tipo === 'VISITA' ? viviendaDe(e.summary, e.location, e.desc) : { idealista_id: '', via: '' };
  const fila = {
    centinela: false, tipo: c.tipo, motivo: c.motivo,
    calendar_id: e.calendar_id, event_id: e.event_id, agente: e.agente || 'General',
    agente_key: e.agente_key || '', agente_enum: AGENTE_ENUM[e.agente_key] || null,
    nombre: nom, telefono: c.tel, idealista_id: viv.idealista_id, vivienda_via: viv.via,
    titulo: (e.summary || '').slice(0, 200), inicioISO, inicio_seg: Math.round(ts / 1000),
    pipeline_id: d.pipeline_id, status_id: d.status_id, gemelos: [],
  };
  vistos.set(clave, fila);
  plan.push(fila);
}

// ── Fail-closed ──
const motivos = [];
if (!agendas.length) motivos.push('no hay agendas que leer');
if (!eventos.length) motivos.push('las agendas han devuelto 0 eventos (minimo 1)');
if (plan.length > 25) motivos.push('saldrian ' + plan.length + ' leads de golpe (maximo 25)');
const seguro = motivos.length === 0;

return [{ json: { dry, seguro, motivos, aplicar: seguro && !dry, plan, marcar, resumen: {
  agendas: agendas.length, eventos: eventos.length, a_crear: plan.length,
  visitas: plan.filter(p => p.tipo === 'VISITA').length,
  valoraciones: plan.filter(p => p.tipo === 'VALORACION').length,
  sin_telefono: plan.filter(p => !p.telefono).length,
  con_vivienda: plan.filter(p => p.idealista_id).length,
  gemelos: [...vistos.values()].reduce((a, v) => a + (v.gemelos ? v.gemelos.length : 0), 0),
  saltados: saltados.length,
  gemelos_a_marcar: marcar.length,
} } }];

const p = $('Clasificar').first().json;
// Siempre al menos un item: un nodo sin entrada no se ejecuta y cortaria la cadena hasta el aviso.
const out = [{ json: { centinela: true } }];
if (p.aplicar) for (const f of p.plan) out.push({ json: f });
return out;

