const P = (x) => { try { return (x && typeof x.data === 'string') ? JSON.parse(x.data) : (x || {}); } catch (e) { return {}; } };
const f = $('Loop').first().json;
const lead = (P($('Crear lead').first().json)._embedded || {}).leads;
return [{ json: { ...f, lead_id: (lead && lead[0] && lead[0].id) || null } }];

const p = $('Clasificar').first().json;
const r = p.resumen;
const hechos = $input.all().map(i => i.json).filter(x => x && x.lead_id);

// Solo se avisa de lo que va MAL. Crear leads es lo normal y con el cron cada 5 min avisar de
// cada acierto enterraria las incidencias reales en #01-incidencias. Devolver 0 items hace que
// 'Avisar en Slack' no llegue a ejecutarse.
// Habla si: el fail-closed ha bloqueado, o se planificaron N leads y no salieron los N.
// La simulacion manual habla siempre: solo corre cuando alguien la lanza a proposito.
const parcial = !p.dry && r.a_crear > 0 && hechos.length !== r.a_crear;
if (!p.dry && p.seguro && !parcial) return [];

const L = [];
if (!p.seguro) {
  L.push('🔴 *Calendario → Kommo: BLOQUEADO, no se ha creado nada*');
  p.motivos.forEach(m => L.push('   • ' + m));
} else if (parcial) {
  L.push('⚠️ *Calendario → Kommo: se planificaron ' + r.a_crear + ' leads y solo se crearon ' + hechos.length + '*');
  L.push('   Revisar la ejecución en n8n antes de volver a lanzar.');
} else {
  L.push('🧪 *Calendario → Kommo (simulación, no se ha escrito nada)*');
}
L.push('Agendas ' + r.agendas + ' · eventos ' + r.eventos + ' · descartados ' + r.saltados
  + (r.gemelos ? ' · ' + r.gemelos + ' citas repetidas en otra agenda' : ''));
if (r.a_crear) {
  L.push('Visitas ' + r.visitas + ' · valoraciones ' + r.valoraciones
    + (r.sin_telefono ? ' · ' + r.sin_telefono + ' sin teléfono (a Pendiente de Asignar)' : ''));
  for (const f of p.plan.slice(0, 15)) {
    L.push('   · ' + f.tipo.toLowerCase() + ' — ' + f.nombre + (f.telefono ? ' ' + f.telefono : ' (sin tel)')
      + ' — ' + f.agente + ' — ' + f.inicioISO.slice(0, 16).replace('T', ' '));
  }
}
return [{ json: { texto: L.join('\n') } }];

// Enriquecer preferencias devuelve la respuesta del subworkflow y pisa el item: sin esto el
// lead_id no vuelve al Loop y 'Aviso' cuenta el lead como no creado (falso positivo del 14-sep).
return [{ json: $('Hecho').first().json }];

// 21-sep-2026: una cita apuntada a mano en DOS agendas genera un solo lead y solo se marcaba el
// evento elegido. Al cancelar se borraba ese y, 5 min despues, el gemelo sin marcar entraba como cita
// nueva: lead fantasma + recordatorios a quien ya habia cancelado (Noemi, 18-sep). Aqui se marca cada
// gemelo con el mismo simarro_lead; asi queda 'ya vinculado' para siempre y la cancelacion lo encuentra.
const p = $('Clasificar').first().json;
if (!p.aplicar) return [];
return (p.marcar || []).map(m => ({ json: m }));
